update writr_info
   set nm = #{nm}
     , act_code = #{actCode}
     , act_area = #{actArea}
     , telno    = #{telno}
     , self_intrcn = #{selfIntrcn}
     , prdct_nm = #{prdctNm}
     , mnfct_year = #{mnfctYear}
     , prdct_dc = #{prdctDc}
     , change_mber_no = #{changeMberNo}
     , change_dt = CURRENT_TIMESTAMP
 where mber_no = #{mberNo}

mapper.select:
with result as ( select a.mber_no , a.rqstdt , a.nm , b.email , a.jdgmn_sttus_code , (select x.code_nm from cmmn_cd x where x.group_code = 'JDGMN_ST' and x.code = a.jdgmn_sttus_code) jdgmn_sttus_nm , (select x.refer1 from cmmn_cd x where x.group_code = 'JDGMN_ST' and x.code = a.jdgmn_sttus_code) jdgmn_refer1_nm , (case when a.jdgmn_sttus_code = 'PEND' then '아직 심사가 시작되지 않았습니다.' when a.jdgmn_sttus_code = 'REVW' then '작가 정보와 작품을 검토하고 있습니다.' else a.jdgmn_sumry end) jdgmn_sumry , c.file_no writr_file_no , c.sn writr_sn , d.file_no reprsnt_prdct_file_no , d.sn reprsnt_prdct_sn , a.creat_dt from writr_info a , mber_info b , file_dtls c , file_dtls d where a.nm like '%' || #{nm} || '%' and a.mber_sttus_code = #{mberSttusCode} and a.gnrl_mber_no = b.mber_no and a.writr_file_no = c.file_no and c.use_at = 'Y' and a.reprsnt_prdct_file_no = d.file_no and d.use_at = 'Y' ), cnt as ( select count(*) all_cnt , count(*) filter (where jdgmn_sttus_code = 'PEND') pend , count(*) filter (where jdgmn_sttus_code = 'REVW') revw , count(*) filter (where jdgmn_sttus_code = 'CMPL') cmpl , count(*) filter (where jdgmn_sttus_code = 'REJT') rejt , count(*) filter (where jdgmn_sttus_code = 'RCHG') rchg from result ), list as ( select * from result where 1=1
and jdgmn_sttus_code = #{jdgmnSttusCode}
) select mber_no , rqstdt , nm , email , jdgmn_sttus_nm , jdgmn_refer1_nm , jdgmn_sumry , writr_file_no , writr_sn , reprsnt_prdct_file_no , reprsnt_prdct_sn , jdgmn_sttus_code , all_cnt , pend , revw , cmpl , rejt , rchg from cnt c left join list l on true order by creat_dt desc limit #{size} offset #{offset}

