update writr_info
   set jdgmn_opinion = #{writrInfoEntity.jdgmnOpinion}
     , jdgmn_sumry = #{writrInfoEntity.jdgmnSumry}
     , jdgmn_sttus_code = #{changeJdgmnSttusCode}
     , jdgmn_sttus_change_dt = CURRENT_TIMESTAMP
     , change_mber_no = #{writrInfoEntity.changeMberNo}
     , change_dt = CURRENT_TIMESTAMP
 where mber_no = #{writrInfoEntity.mberNo}
   and jdgmn_sttus_code = #{writrInfoEntity.jdgmnSttusCode}
   and mber_sttus_code = #{writrInfoEntity.mberSttusCode}
